                    "sql": "create or replace table snitch_db.maplemonk.og_demand_plan as WITH fixed_data AS ( SELECT d1.\"L1 Category\" AS L1_Category, d1.\"CATEGORY\" AS Category, d1.\"01/01/2025\" AS Jan_Online_Cat_Mix, d1.\"01/02/2025\" AS Feb_Online_Cat_Mix, d1.\"01/03/2025\" AS Mar_Online_Cat_Mix, d1.\"01/04/2025\" AS Apr_Online_Cat_Mix, d1.\"01/05/2025\" AS May_Online_Cat_Mix, d1.\"01/06/2025\" AS Jun_Online_Cat_Mix, d1.\"01/07/2025\" AS Jul_Online_Cat_Mix, d1.\"01/08/2025\" AS Aug_Online_Cat_Mix, d1.\"01/09/2025\" AS Sep_Online_Cat_Mix, d1.\"01/10/2025\" AS Oct_Online_Cat_Mix, d1.\"01/11/2025\" AS Nov_Online_Cat_Mix, d1.\"01/12/2025\" AS Dec_Online_Cat_Mix, d2.\"01/01/2025\" AS Jan_Fresh_MOQ, d2.\"01/02/2025\" AS Feb_Fresh_MOQ, d2.\"01/03/2025\" AS Mar_Fresh_MOQ, d2.\"01/04/2025\" AS Apr_Fresh_MOQ, d2.\"01/05/2025\" AS May_Fresh_MOQ, d2.\"01/06/2025\" AS Jun_Fresh_MOQ, d2.\"01/07/2025\" AS Jul_Fresh_MOQ, d2.\"01/08/2025\" AS Aug_Fresh_MOQ, d2.\"01/09/2025\" AS Sep_Fresh_MOQ, d2.\"01/10/2025\" AS Oct_Fresh_MOQ, d2.\"01/11/2025\" AS Nov_Fresh_MOQ, d2.\"01/12/2025\" AS Dec_Fresh_MOQ, CAST(REPLACE(d3.\"01/01/2025\", \',\', \'\') AS FLOAT) * (31 - EXTRACT(DAY FROM CURRENT_DATE)) / 31 AS Jan_Inwards, CASE WHEN EXTRACT(MONTH FROM CURRENT_DATE) = 2 THEN CAST(REPLACE(d3.\"01/02/2025\", \',\', \'\') AS FLOAT) * (28 - EXTRACT(DAY FROM CURRENT_DATE)) / 28 ELSE CAST(REPLACE(d3.\"01/02/2025\", \',\', \'\') AS FLOAT) END AS Feb_Inwards, d4.\"01/01/2025\" AS Jan_Fresh_Perc, d4.\"01/02/2025\" AS Feb_Fresh_Perc, d4.\"01/03/2025\" AS Mar_Fresh_Perc, d4.\"01/04/2025\" AS Apr_Fresh_Perc, d4.\"01/05/2025\" AS May_Fresh_Perc, d4.\"01/06/2025\" AS Jun_Fresh_Perc, d4.\"01/07/2025\" AS Jul_Fresh_Perc, d4.\"01/08/2025\" AS Aug_Fresh_Perc, d4.\"01/09/2025\" AS Sep_Fresh_Perc, d4.\"01/10/2025\" AS Oct_Fresh_Perc, d4.\"01/11/2025\" AS Nov_Fresh_Perc, d4.\"01/12/2025\" AS Dec_Fresh_Perc, d1.\"Target DOI\" AS Ideal_DOI, d5.\"01/01/2025\" AS Jan_Offline_Cat_Mix, d5.\"01/02/2025\" AS Feb_Offline_Cat_Mix, d5.\"01/03/2025\" AS Mar_Offline_Cat_Mix, d5.\"01/04/2025\" AS Apr_Offline_Cat_Mix, d5.\"01/05/2025\" AS May_Offline_Cat_Mix, d5.\"01/06/2025\" AS Jun_Offline_Cat_Mix, d5.\"01/07/2025\" AS Jul_Offline_Cat_Mix, d5.\"01/08/2025\" AS Aug_Offline_Cat_Mix, d5.\"01/09/2025\" AS Sep_Offline_Cat_Mix, d5.\"01/10/2025\" AS Oct_Offline_Cat_Mix, d5.\"01/11/2025\" AS Nov_Offline_Cat_Mix, d5.\"01/12/2025\" AS Dec_Offline_Cat_Mix, d6.\"01/01/2025\" AS Jan_Repeat_MOQ, d6.\"01/02/2025\" AS Feb_Repeat_MOQ, d6.\"01/03/2025\" AS Mar_Repeat_MOQ, d6.\"01/04/2025\" AS Apr_Repeat_MOQ, d6.\"01/05/2025\" AS May_Repeat_MOQ, d6.\"01/06/2025\" AS Jun_Repeat_MOQ, d6.\"01/07/2025\" AS Jul_Repeat_MOQ, d6.\"01/08/2025\" AS Aug_Repeat_MOQ, d6.\"01/09/2025\" AS Sep_Repeat_MOQ, d6.\"01/10/2025\" AS Oct_Repeat_MOQ, d6.\"01/11/2025\" AS Nov_Repeat_MOQ, d6.\"01/12/2025\" AS Dec_Repeat_MOQ, FROM snitch_db.maplemonk.gs_online_cat_mix AS d1 JOIN snitch_db.maplemonk.gs_fresh_moq AS d2 ON d1.\"L1 Category\" = d2.\"L1 Category\" AND d1.\"CATEGORY\" = d2.\"CATEGORY\" JOIN snitch_db.maplemonk.gs_inward_projection AS d3 ON d1.\"L1 Category\" = d3.\"L1 Category\" AND d1.\"CATEGORY\" = d3.\"CATEGORY\" JOIN snitch_db.maplemonk.gs_fresh_perc AS d4 ON d1.\"L1 Category\" = d4.\"L1 Category\" AND d1.\"CATEGORY\" = d4.\"CATEGORY\" JOIN snitch_db.maplemonk.gs_offline_cat_mix AS d5 ON d1.\"L1 Category\" = d5.\"L1 Category\" AND d1.\"CATEGORY\" = d5.\"CATEGORY\" JOIN snitch_db.maplemonk.gs_repeat_moq AS d6 ON d1.\"L1 Category\" = d6.\"L1 Category\" AND d1.\"CATEGORY\" = d6.\"CATEGORY\" ), d7_sums AS ( SELECT \"L1_CATEGORY\" AS L1_Category, \"CATEGORY\" AS Category, SUM(\"ONLINE_INVENTORY\") AS WH_Inv, SUM(\"SHOPIFY_RETURNS30\") AS SHOPIFY_RETURNS30, SUM(\"MARKETPLACE_RETURNS30\") AS MARKETPLACE_RETURNS30, SUM(\"SHOPIFY_QUANT30\") AS SHOPIFY_QUANT30, SUM(\"MP_QUANT30\") AS MARKETPLACE_QUANT30, FROM snitch_db.maplemonk.category_journey GROUP BY \"L1_CATEGORY\", \"CATEGORY\" ), sales_data AS ( SELECT SUM(SHOPIFY_RETURNS30) AS Tot_SHOPIFY_RETURNS30, SUM(MARKETPLACE_RETURNS30) AS Tot_MARKETPLACE_RETURNS30, SUM(SHOPIFY_QUANT30) AS Tot_SHOPIFY_QUANT30, SUM(MARKETPLACE_QUANT30) AS Tot_MP_QUANT30, SUM(MARKETPLACE_RETURNS30) AS Tot_MP_RETURNS30, (1 - (Tot_SHOPIFY_RETURNS30 + Tot_MARKETPLACE_RETURNS30)/ NULLIF(Tot_SHOPIFY_QUANT30 + Tot_MP_QUANT30, 0)) * (Tot_SHOPIFY_QUANT30 + Tot_MP_QUANT30) AS Jan_Tot_Sales FROM d7_sums ), Jan_Sales AS ( SELECT SUM(Jan_Tot_Sales) AS Total_Jan_Sales FROM sales_data ), Feb_Sales AS ( SELECT m1.Total_Jan_Sales, Total_Jan_Sales * (1 - 0.07) AS Feb_Tot_Sales FROM Jan_Sales AS m1 ), Mar_Sales AS ( SELECT SUM (m2.Feb_Tot_Sales) AS Total_Feb_Sales, Total_Feb_Sales * (1 + 0.2) AS Mar_Tot_Sales FROM Feb_Sales as m2 ), Apr_Sales AS ( SELECT SUM (m3.Mar_Tot_Sales) AS Total_Mar_Sales, Total_Mar_Sales * (1 + 0.02) AS Apr_Tot_Sales FROM Mar_Sales as m3 ), May_Sales AS ( SELECT SUM(m4.Apr_Tot_Sales) AS Total_Apr_Sales, Total_Apr_Sales * (1 + 0.02) AS May_Tot_Sales FROM Apr_Sales as m4 ), Jun_Sales AS ( SELECT SUM(m5.May_Tot_Sales) AS Total_May_Sales, Total_May_Sales * (1 + 0.04) AS Jun_Tot_Sales FROM May_Sales as m5 ), Jul_Sales AS ( SELECT SUM(m6.Jun_Tot_Sales) AS Total_Jun_Sales, Total_Jun_Sales * (1 + 0.04) AS Jul_Tot_Sales FROM Jun_Sales as m6 ), Aug_Sales AS ( SELECT SUM(m7.Jul_Tot_Sales) AS Total_Jul_Sales, Total_Jul_Sales * (1 + 0.04) AS Aug_Tot_Sales FROM Jul_Sales as m7 ), Sep_Sales AS ( SELECT SUM(m8.Aug_Tot_Sales) AS Total_Aug_Sales, Total_Aug_Sales * (1 + 0.04) AS Sep_Tot_Sales FROM Aug_Sales as m8 ), Oct_Sales AS ( SELECT SUM(m9.Sep_Tot_Sales) AS Total_Sep_Sales, Total_Sep_Sales * (1 + 0.04) AS Oct_Tot_Sales FROM Sep_Sales as m9 ), Nov_Sales AS ( SELECT SUM(m10.Oct_Tot_Sales) AS Total_Oct_Sales, Total_Oct_Sales * (1 + 0.04) AS Nov_Tot_Sales FROM Oct_Sales as m10 ), Dec_Sales AS ( SELECT SUM(m11.Nov_Tot_Sales) AS Total_Nov_Sales, Total_Nov_Sales * (1 + 0.04) AS Dec_Tot_Sales FROM Nov_Sales as m11 ), Dec_Fin_Sales AS ( SELECT SUM(m12.Dec_Tot_Sales) AS Total_Dec_Sales, FROM Dec_Sales as m12 ), calculated_data AS ( SELECT mon1.Total_Jan_Sales, mon2.Total_Feb_Sales, mon3.Total_Mar_Sales, mon4.Total_Apr_Sales, mon5.Total_May_Sales, mon6.Total_Jun_Sales, mon7.Total_Jul_Sales, mon8.Total_Aug_Sales, mon9.Total_Sep_Sales, mon10.Total_Oct_Sales, mon11.Total_Nov_Sales, mon12.Total_Dec_Sales, d7.WH_Inv AS Current_WH_Inv, d7.SHOPIFY_RETURNS30, d7.MARKETPLACE_RETURNS30, d7.SHOPIFY_QUANT30, d7.MARKETPLACE_QUANT30, fd.*, CASE WHEN EXTRACT(MONTH FROM CURRENT_DATE) = 1 THEN mon1.Total_Jan_Sales * fd.Jan_Online_Cat_Mix * (31 - EXTRACT(DAY FROM CURRENT_DATE)) / 31 ELSE mon1.Total_Jan_Sales * fd.Jan_Online_Cat_Mix END AS Jan_Online_Sales, CASE WHEN EXTRACT(MONTH FROM CURRENT_DATE) = 2 THEN mon2.Total_Feb_Sales * fd.Feb_Online_Cat_Mix * (28 - EXTRACT(DAY FROM CURRENT_DATE)) / 28 ELSE mon2.Total_Feb_Sales * fd.Feb_Online_Cat_Mix END AS Feb_Online_Sales, CASE WHEN EXTRACT(MONTH FROM CURRENT_DATE) = 3 THEN mon3.Total_Mar_Sales * fd.Mar_Online_Cat_Mix * (31 - EXTRACT(DAY FROM CURRENT_DATE)) / 31 ELSE mon3.Total_Mar_Sales * fd.Mar_Online_Cat_Mix END AS Mar_Online_Sales, CASE WHEN EXTRACT(MONTH FROM CURRENT_DATE) = 4 THEN mon4.Total_Apr_Sales * fd.Apr_Online_Cat_Mix * (30 - EXTRACT(DAY FROM CURRENT_DATE)) / 30 ELSE mon4.Total_Apr_Sales * fd.Apr_Online_Cat_Mix END AS Apr_Online_Sales, CASE WHEN EXTRACT(MONTH FROM CURRENT_DATE) = 5 THEN mon5.Total_May_Sales * fd.May_Online_Cat_Mix * (31 - EXTRACT(DAY FROM CURRENT_DATE)) / 31 ELSE mon5.Total_May_Sales * fd.May_Online_Cat_Mix END AS May_Online_Sales, CASE WHEN EXTRACT(MONTH FROM CURRENT_DATE) = 6 THEN mon6.Total_Jun_Sales * fd.Jun_Online_Cat_Mix * (30 - EXTRACT(DAY FROM CURRENT_DATE)) / 30 ELSE mon6.Total_Jun_Sales * fd.Jun_Online_Cat_Mix END AS Jun_Online_Sales, CASE WHEN EXTRACT(MONTH FROM CURRENT_DATE) = 7 THEN mon7.Total_Jul_Sales * fd.Jul_Online_Cat_Mix * (31 - EXTRACT(DAY FROM CURRENT_DATE)) / 31 ELSE mon7.Total_Jul_Sales * fd.Jul_Online_Cat_Mix END AS Jul_Online_Sales, CASE WHEN EXTRACT(MONTH FROM CURRENT_DATE) = 8 THEN mon8.Total_Aug_Sales * fd.Aug_Online_Cat_Mix * (31 - EXTRACT(DAY FROM CURRENT_DATE)) / 31 ELSE mon8.Total_Aug_Sales * fd.Aug_Online_Cat_Mix END AS Aug_Online_Sales, CASE WHEN EXTRACT(MONTH FROM CURRENT_DATE) = 9 THEN mon9.Total_Sep_Sales * fd.Sep_Online_Cat_Mix * (30 - EXTRACT(DAY FROM CURRENT_DATE)) / 30 ELSE mon9.Total_Sep_Sales * fd.Sep_Online_Cat_Mix END AS Sep_Online_Sales, CASE WHEN EXTRACT(MONTH FROM CURRENT_DATE) = 10 THEN mon10.Total_Oct_Sales * fd.Oct_Online_Cat_Mix * (31 - EXTRACT(DAY FROM CURRENT_DATE)) / 31 ELSE mon10.Total_Oct_Sales * fd.Oct_Online_Cat_Mix END AS Oct_Online_Sales, CASE WHEN EXTRACT(MONTH FROM CURRENT_DATE) = 11 THEN mon11.Total_Nov_Sales * fd.Nov_Online_Cat_Mix * (30 - EXTRACT(DAY FROM CURRENT_DATE)) / 30 ELSE mon11.Total_Nov_Sales * fd.Nov_Online_Cat_Mix END AS Nov_Online_Sales, CASE WHEN EXTRACT(MONTH FROM CURRENT_DATE) = 12 THEN mon12.Total_Dec_Sales * fd.Dec_Online_Cat_Mix * (31 - EXTRACT(DAY FROM CURRENT_DATE)) / 31 ELSE mon12.Total_Dec_Sales * fd.Dec_Online_Cat_Mix END AS Dec_Online_Sales, CASE WHEN LOWER(fd.Category) IN (\'hoodies\', \'sweaters\') THEN 0 ELSE 1 END AS sunset, CASE WHEN EXTRACT(MONTH FROM CURRENT_DATE) = 1 THEN CAST(REPLACE((SELECT \"01/01/2025\" FROM snitch_db.maplemonk.gs_Offline_stores WHERE TYPE = \'NSO\'), \',\', \'\') AS FLOAT) * Jan_Offline_Cat_Mix * (31 - EXTRACT(DAY FROM CURRENT_DATE)) / 31 ELSE CAST(REPLACE((SELECT \"01/01/2025\" FROM snitch_db.maplemonk.gs_Offline_stores WHERE TYPE = \'NSO\'), \',\', \'\') AS FLOAT) * Jan_Offline_Cat_Mix END AS NSO_Jan, CASE WHEN EXTRACT(MONTH FROM CURRENT_DATE) = 2 THEN CAST(REPLACE((SELECT \"01/02/2025\" FROM snitch_db.maplemonk.gs_Offline_stores WHERE TYPE = \'NSO\'), \',\', \'\') AS FLOAT) * Feb_Offline_Cat_Mix * (CASE WHEN EXTRACT(MONTH FROM CURRENT_DATE) = 2 AND MOD(EXTRACT(YEAR FROM CURRENT_DATE), 4) = 0 AND (MOD(EXTRACT(YEAR FROM CURRENT_DATE), 100) != 0 OR MOD(EXTRACT(YEAR FROM CURRENT_DATE), 400) = 0) THEN 29 ELSE 28 END - E